#include "display_cli.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <string>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <unistd.h>

// ---------------------------------------------------------------------------
// Bottom status display: pinned bottom lines on the terminal + dedicated .log
//
// Row layout (tty):  rows-1 -> flight time line, rows -> battery bar line.
// The two lines are independent printf sequences (save cursor -> move -> clear
// -> print -> restore cursor), so they never scroll and stay pinned after the
// flight ends; the 5 Hz redraw also heals corruption caused by ROS console
// output flushing between the sequences.
//
// This runs on a timer thread while the data feeds run on the main thread.
// spinOnce() is deliberately non-blocking and only reads, so the shared data
// objects stay race-free in practice (same pattern as Battery_Data_t before).
//
// Flight time is display-only: in-air is judged from PX4's land detector via
// /mavros/extended_state (IN_AIR/TAKEOFF/LANDING count as flying), falling
// back to `armed` when the message is stale (>2 s). A 3-sample debounce
// (~0.6 s at 5 Hz) keeps a bouncy touchdown from being counted twice.
// ---------------------------------------------------------------------------

static std::string render_battery_bar(double pct, double volt,
                                      double cmax, double cmin,
                                      double cmax_volt, double cmin_volt,
                                      int bar_width)
{
    if (cmax < 0.0)
        return "BAT [no battery data]";

    int filled = static_cast<int>(std::floor(pct * bar_width + 0.5));
    if (filled < 0)
        filled = 0;
    if (filled > bar_width)
        filled = bar_width;

    char buf[256];
    std::string bar(static_cast<size_t>(filled), '#');
    bar += std::string(static_cast<size_t>(bar_width - filled), '-');
    std::snprintf(buf, sizeof(buf),
                  "BAT [%s] %3.0f%% %.2fV | cmax %3.0f%%@%.2fV cmin %3.0f%%@%.2fV",
                  bar.c_str(), pct * 100.0, volt,
                  cmax * 100.0, cmax_volt, cmin * 100.0, cmin_volt);
    return std::string(buf);
}

static std::string render_flight_line(double total_sec, bool in_air)
{
    long s = static_cast<long>(total_sec);
    char buf[64];
    std::snprintf(buf, sizeof(buf), 
                  "FLY total %02ld:%02ld",
                  (s % 3600) / 60, s % 60);
    return std::string(buf);
}

static void make_dirs_recursive(const std::string &dir)
{
    std::string cur;
    for (size_t i = 0; i < dir.size(); ++i)
    {
        cur += dir[i];
        if (dir[i] == '/' || i == dir.size() - 1)
        {
            if (!cur.empty() && cur != "/")
                mkdir(cur.c_str(), 0755);
        }
    }
}

DisplayCLI::DisplayCLI(const Parameter_t::DisplayCli &p)
    : bar_width_(p.bar_width > 0 ? p.bar_width : 1)
{
    tty_ = p.bottom_bar_enable && isatty(fileno(stdout));

    if (p.log_enable)
    {
        std::string dir = p.log_dir;
        if (dir.empty())
        {
            const char *home = std::getenv("HOME");
            dir = std::string(home ? home : "/tmp") + "/.ros/px4ctrl_battery";
        }
        make_dirs_recursive(dir);

        char name[64];
        std::time_t t = std::time(nullptr);
        std::strftime(name, sizeof(name), "battery_%Y%m%d_%H%M%S.log", std::localtime(&t));
        log_file_.open(dir + "/" + name);
        if (log_file_.is_open())
        {
            ROS_INFO_STREAM("[px4ctrl] Battery log: " << dir + "/" + name);
        }
        else
        {
            ROS_WARN_STREAM("[px4ctrl] Cannot open battery log in " << dir << ", bottom bar only.");
        }
    }

    const ros::WallTime now = ros::WallTime::now();
    last_spin_wall_ = now;
    last_render_ = now;
    last_log_ = now;
}

void DisplayCLI::updateFlightTime(double dt, const mavros_msgs::ExtendedState &ext,
                                  const mavros_msgs::State &fcu_state)
{
    bool raw;
    if ((ros::Time::now() - ext.header.stamp) > ros::Duration(2.0))
    {
        // extended_state stale: fall back to armed as a rough proxy.
        raw = fcu_state.armed;
    }
    else
    {
        raw = ext.landed_state == mavros_msgs::ExtendedState::LANDED_STATE_IN_AIR ||
              ext.landed_state == mavros_msgs::ExtendedState::LANDED_STATE_TAKEOFF ||
              ext.landed_state == mavros_msgs::ExtendedState::LANDED_STATE_LANDING;
    }

    if (raw == in_air_)
    {
        air_debounce_ = 0;
    }
    else if (++air_debounce_ >= 3)
    {
        in_air_ = raw;
        air_debounce_ = 0;
    }

    // Integrate on the wall clock; cap dt so a stalled timer cannot add a
    // bogus burst of flight time.
    if (in_air_ && dt > 0.0)
        total_flight_sec_ += std::min(dt, 1.0);
}

void DisplayCLI::spinOnce(Battery_Data_t &bat, ExtendedState_Data_t &ext, State_Data_t &fcu_state)
{
    const ros::WallTime now = ros::WallTime::now();
    const double dt = (now - last_spin_wall_).toSec();
    last_spin_wall_ = now;
    updateFlightTime(dt, ext.current_extended_state, fcu_state.current_state);

    if (started_ && (now - last_render_).toSec() < 0.2) // throttle to 5 Hz
        return;
    started_ = true;
    last_render_ = now;

    const double v = bat.volt;
    const double pct = bat.percentage;
    const int samples = bat.sample_count;

    const bool has_data = samples > 0;
    // Preparation period: the LPF starts from 0 and each sample washes out 20%
    // of it, so wait for 21 samples (0.8^21 < 1% residual, ~4s at 5 Hz) before
    // trusting the filtered voltage. Nothing is displayed and no extremes are
    // recorded during this period.
    const bool ready = samples >= 21;

    if (ready && !std::isnan(pct))
    {
        if (cmax_pct_ < 0.0) // first valid sample
        {
            cmax_pct_ = cmin_pct_ = pct;
            cmax_v_ = cmin_v_ = v;
        }
        else
        {
            if (pct > cmax_pct_)
            {
                cmax_pct_ = pct;
                cmax_v_ = v;
            }
            if (pct < cmin_pct_)
            {
                cmin_pct_ = pct;
                cmin_v_ = v;
            }
        }
    }

    const std::string bat_line = !has_data ? "BAT [no battery data]"
                                 : !ready    ? "BAT [battery data preparing...]"
                                             : render_battery_bar(pct, v, cmax_pct_, cmin_pct_,
                                                                  cmax_v_, cmin_v_, bar_width_);
    const std::string fly_line = render_flight_line(total_flight_sec_, in_air_);

    if (tty_)
    {
        struct winsize ws;
        int rows = 24;
        if (ioctl(fileno(stdout), TIOCGWINSZ, &ws) == 0 && ws.ws_row > 0)
            rows = ws.ws_row;
        const int fly_row = rows > 1 ? rows - 1 : rows;
        std::printf("\0337\033[%d;1H\033[2K%s\0338", fly_row, fly_line.c_str());
        std::printf("\0337\033[%d;1H\033[2K%s\0338", rows, bat_line.c_str());
        std::fflush(stdout);
    }

    if (log_file_.is_open() && (now - last_log_).toSec() >= 1.0) // 1 Hz log
    {
        last_log_ = now;
        char ts[32];
        std::time_t t = std::time(nullptr);
        std::strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", std::localtime(&t));
        log_file_ << ts << "  " << bat_line << "  |  " << fly_line << std::endl; // endl flushes
    }
}
